[583] = { en = "Welcome to the Jungle", tier = 2,
  t = "Welkom in de jungle",
  d = "Welkom in Stranglethorn!$b$bMisschien weet je het niet, maar die dwerg daar is de enige echte Hemet Nesingwary: de beroemde oorlogsheld van de Alliance en een meester in het jagen op groot wild. Hij laat niet graag vreemden in zijn kamp, maar jij ziet eruit alsof je in je leven al heel wat hebt meegemaakt, $c.$b$bMeester Nesingwary heeft zelf in veel gevechten gevochten, dus hij heeft een zwak voor andere helden.$b$bGa met hem praten. Misschien kan hij je een paar tips over jagen geven.",
  o = "Spreek met Hemet Nesingwary.",
  c = "Zeer aangenaam kennis met je te maken, $n. Ik heb hier al een tijd geen $c meer gezien.$b$bIk heb me bij deze expeditie aangesloten met één doel: jagen op een groot beest dat moeilijk te vinden is. Omdat je een soort held bent, wil ik je wel laten meedoen aan de jacht. Maar eerst moet je jezelf bewijzen.$b$bIk leer je hoe je raptors doodt. Ajeck leert je jagen op tijgers. En Sir Erlgadin is een meester in het opsporen van panters.$b$bBewijs wat je kunt, dan mag je meedoen aan de grote jacht.",
  g = { {"de enige echte", "the one and only"}, {"beroemde", "renowned (beroemd)"}, {"oorlogsheld", "war hero"}, {"groot wild", "big game"}, {"vreemden", "strangers (vreemde)"}, {"heel wat ... meegemaakt", "seen quite a bit of action (meemaken)"}, {"een zwak voor", "a soft spot for"}, {"tips", "pointers, tips"}, {"Zeer aangenaam kennis met je te maken", "jolly nice to make your acquaintance"}, {"expeditie", "expedition"}, {"aangesloten", "joined (zich aansluiten)"}, {"doel", "purpose, goal"}, {"jacht", "hunt"}, {"opsporen", "tracking"}, {"panters", "panthers (panter)"} },
},

[185] = { en = "Tiger Mastery", tier = 2,
  t = "Meester in tijgers",
  d = "Toen ik nog een jong meisje was, leerde mijn vader me de kunst van het jagen op tijgers.$b$bDe jonge katachtigen zijn veel makkelijker op te sporen en te doden. Daarom beginnen we makkelijk. Je vindt vaak jonge tijgers in de buurt van het kamp van de expeditie.$b$bTest je speurkunsten en kijk of je een paar van die beesten kunt opjagen.",
  o = "Ajeck Rouack van Nesingwary's Expedition wil dat je 10 Young Stranglethorn Tigers doodt.",
  p = "Ik voel me niet zeker genoeg om je verder te trainen, $n, tot je hebt bewezen dat je de jongste tijgers kunt doden.",
  c = "Mooi gedaan, $n. Je bent klaar voor de volgende stap.",
  g = { {"Meester", "master"}, {"kunst", "art"}, {"katachtigen", "felines (katachtige)"}, {"op te sporen", "to track (opsporen)"}, {"in de buurt van", "near"}, {"expeditie", "expedition"}, {"speurkunsten", "tracking skills"}, {"opjagen", "to hunt down"}, {"zeker", "confident, sure"}, {"trainen", "to train"}, {"bewezen", "proven (bewijzen)"} },
},

[190] = { en = "Panther Mastery", tier = 2,
  t = "Meester in panters",
  d = "Als je mee wilt doen aan de jacht met deze topgroep die Hemet heeft verzameld, moet je bewijzen dat je een goede panterjager bent. We beginnen makkelijk, maak je geen zorgen. Laat eerst maar eens zien dat je 10 jonge panters kunt doden.$b$bZe opsporen is maar de helft van de uitdaging...",
  o = "Sir S. J. Erlgadin van Nesingwary's Expedition wil dat je 10 Young Panthers doodt.",
  p = "Een echte panterjager zou buiten op het veld zijn om zijn prooi te besluipen. Laat zien dat je je doel serieus neemt, $c, en ga weer naar buiten.",
  c = "Een goed begin, $N!",
  g = { {"jacht", "hunt"}, {"topgroep", "crack group"}, {"verzameld", "assembled (verzamelen)"}, {"panterjager", "panther hunter"}, {"opsporen", "tracking down"}, {"helft", "half"}, {"uitdaging", "challenge"}, {"veld", "field"}, {"prooi", "prey"}, {"besluipen", "to stalk"}, {"serieus neemt", "take seriously (serieus nemen)"} },
},

[575] = { en = "Supply and Demand", tier = 2,
  t = "Vraag en aanbod",
  d = "\"De beste leerbewerker van de South Seas en van de oude en de nieuwe wereld.\" Zo noemen ze me. Mij! Drizzlik! De beste leer... Ahum. Nou ja.$b$bMijn leren spullen staan overal bekend als de allermooiste, de keuze van de kenner!$b$bIk heb net een bestelling gekregen van Director Riddlevox van de Tinkers' Union: twaalf paar van zijn favoriete laarzen uit de Excelsior-lijn. Eigenlijk onze bestsellers.$b$bOm met de basisvorm te beginnen, heb ik krokoliskhuiden nodig van de krokodillen langs de rivier in het noorden van Stranglethorn.",
  o = "Breng 2 Large River Crocolisk Skins naar Drizzlik in Booty Bay.",
  p = "Mijn gereedschap is helemaal klaar, $n. Ik heb alleen die huiden nodig. We willen Riddlevox niet laten wachten, dat is zeker.$b$bHet is voor niemand een goed idee om de hoofduitvinder van de Tinkers' Union ontevreden te laten.",
  c = "Deze huiden zijn goed genoeg. Hun kwaliteit is niet zo belangrijk, omdat ze de binnenlaag van de laarzen worden. Maar het is wel belangrijk dat ze comfortabel zijn.$b$bAls ze een beetje te stijf zijn, gebruik ik wat tijgerbloed om ze zachter te maken. Trucjes van het vak, weet je wel?",
  g = { {"Vraag en aanbod", "supply and demand"}, {"leerbewerker", "leathercrafter"}, {"leren", "leather (adjective)"}, {"staan ... bekend", "are known (bekendstaan)"}, {"allermooiste", "most exquisite"}, {"kenner", "connoisseur"}, {"bestelling", "order"}, {"basisvorm", "basic shape"}, {"krokoliskhuiden", "crocolisk skins"}, {"gereedschap", "equipment, tools"}, {"hoofduitvinder", "chief inventor"}, {"ontevreden", "unsatisfied"}, {"binnenlaag", "inside layer"}, {"stijf", "rigid, stiff"}, {"Trucjes van het vak", "tricks of the trade"} },
},

[198] = { en = "Supplies to Private Thorsen", tier = 2,
  t = "Voorraden voor Private Thorsen",
  d = "Hm. Ja, ik heb eigenlijk wel iets wat je kunt doen. Lieutenant Doren en zijn volgelingen in het noorden hebben hun vaste voorraden van ons nodig.$b$bZe zijn niet bezorgd, en nu de trollen aanvallen, heb ik iemand nodig die het doet. Het kamp van Doren ligt ten noordwesten van de weg bij de ingang van Stranglethorn vanuit Duskwood. Geef de voorraden aan Private Thorsen. Als hij niet in het kamp is, patrouilleert hij ten zuiden ervan. Hij zorgt er verder voor.$b$bLet op: als het je niet lukt, moet je me schadevergoeding betalen.",
  o = "Bezorg de Miscellaneous Goblin Supplies bij Private Thorsen.",
  p = "Ja? Wat wil je? O, voorraden van de goblins. Vreemd dat een $R ze komt brengen; meestal sturen ze hun eigen mensen. Maakt niet uit... je hebt ze toch niet aangeraakt? Goed, goed... we willen niet dat er iets met onze mijnen gebeurt, o nee.",
  c = "Met deze landmijnen kunnen we ons verdedigen tegen dat beest Kurzen en zijn mannen. Bedankt dat je ze hebt gebracht. Als je meer werk zoekt, kan ik waarschijnlijk wel iets voor je vinden. En dan hoef je niet met die goblins te maken te hebben, hm?",
  g = { {"Voorraden", "supplies (voorraad)"}, {"volgelingen", "followers (volgeling)"}, {"vaste", "regular (vast)"}, {"bezorgd", "delivered (bezorgen)"}, {"ingang", "entrance"}, {"patrouilleert", "patrols (patrouilleren)"}, {"Let op", "mind you"}, {"schadevergoeding", "restitution, compensation"}, {"Bezorg", "deliver (bezorgen)"}, {"aangeraakt", "touched (aanraken)"}, {"mijnen", "mines (mijn)"}, {"landmijnen", "land mines"}, {"verdedigen", "to defend"}, {"te maken te hebben", "to deal with (te maken hebben met)"} },
},

[201] = { en = "Investigate the Camp", tier = 2,
  t = "Onderzoek het kamp",
  d = "Ik heb berichten gekregen over een groep jagers die een kamp hebben opgezet stroomopwaarts van het mijnkamp van de Venture Company bij Lake Nazferiti. Normaal zou het me niets kunnen schelen, maar ik hoorde iets wat haast niet te geloven is: Hemet Nesingwary zou een van de jagers daar zijn? Hij heeft zeker goede connecties, als je begrijpt wat ik bedoel, en je kunt nooit voorzichtig genoeg zijn.$b$bWaarom ga je niet eens naar dat kamp kijken, $n, en zien wat ze van plan zijn?",
  o = "Vind het kamp van de jagers en meld de plek aan Krazek in Booty Bay.",
  p = "En? Heb je het kamp kunnen vinden?",
  c = "Hmm, dus mijn informatie klopte, zoals altijd. Interessant. Nou, ik denk niet dat ze een gevaar zijn voor onze bedrijvigheid hier. Maar misschien hebben ze wel iets nodig van onze uitstekende fabrieksproducten. Hmm...",
  e = "Vind het kamp van de jagers",
  g = { {"Onderzoek", "investigate (onderzoeken)"}, {"berichten", "reports (bericht)"}, {"opgezet", "set up (opzetten)"}, {"stroomopwaarts", "upriver"}, {"mijnkamp", "mining camp"}, {"haast niet te geloven", "hard to believe, improbable"}, {"connecties", "connections"}, {"voorzichtig", "careful, safe"}, {"van plan", "planning, about"}, {"meld", "report (melden)"}, {"klopte", "was correct (kloppen)"}, {"bedrijvigheid", "operation, business"}, {"fabrieksproducten", "manufactured products"} },
},

[186] = { en = "Tiger Mastery", tier = 2,
  t = "Meester in tijgers",
  d = "Je leert, $c. Laten we je vaardigheden nu testen met de volwassen katten. Dood deze keer 10 Stranglethorn Tigers.",
  o = "Ajeck Rouack van Nesingwary's Expedition wil dat je 10 Stranglethorn Tigers doodt.",
  p = "Als je grotere uitdagingen wilt, moet je jezelf eerst bewijzen met de taak die je nu hebt. Kom terug als je 10 Stranglethorn Tigers hebt gedood.",
