[191] = { en = "Panther Mastery", tier = 2,
  t = "Meester in panters",
  d = "Nu ben je klaar om er een schepje bovenop te doen. Als je wilt bewijzen dat je goed genoeg bent om met grootwildjagers zoals deze om te gaan, moet je laten zien dat je 10 panters kunt doden.$b$bDie grote jongens zijn sterker. Ze zijn niet zo makkelijk als de jonge die je eerder doodde.",
  o = "Sir S. J. Erlgadin van Nesingwary's Expedition wil dat je 10 Panthers doodt.",
  p = "Ga 10 panters doden! Laat zien wat je kunt!",
  c = "Perfect uitgevoerd, $N!",
  g = { {"er een schepje bovenop te doen", "to turn it up a notch"}, {"bewijzen", "to prove"}, {"grootwildjagers", "big game hunters (grootwildjager)"}, {"om te gaan", "to socialize, associate (omgaan)"}, {"panters", "panthers (panter)"}, {"sterker", "tougher, stronger (sterk)"}, {"uitgevoerd", "executed (uitvoeren)"} },
